contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient test balance");

        uint balanceBefore = address(c).balance;
        uint myBalanceBefore = address(this).balance;

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint balanceAfterDeposit = address(c).balance;
        require(balanceAfterDeposit >= balanceBefore, "deposit decreased balance");

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint finalContractBalance = address(c).balance;
        uint myFinalBalance = address(this).balance;

        assert(
            finalContractBalance <= balanceAfterDeposit &&
            myFinalBalance >= myBalanceBefore - amount &&
            (finalContractBalance < balanceAfterDeposit) == (myFinalBalance > myBalanceBefore - amount)
        );
    }

    receive() external payable {}
}

