pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint balanceBefore = address(c).balance;
        uint myBalanceBefore = address(this).balance;
        try c.deposit{value: amount}() {} catch { return; }
        uint balanceAfterDeposit = address(c).balance;
        vm.assume(balanceAfterDeposit >= balanceBefore);
        try c.withdrawAll() {} catch { return; }
        uint finalContractBalance = address(c).balance;
        uint myFinalBalance = address(this).balance;
        assertTrue(finalContractBalance <= balanceAfterDeposit &&
            myFinalBalance >= myBalanceBefore - amount &&
            (finalContractBalance < balanceAfterDeposit) == (myFinalBalance > myBalanceBefore - amount));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
